      s = { id, rowIds: [], meta: { cachedValue: v, overlapBucket: b } };
      map.set(id, s);
    }
    s.rowIds.push(c.rowId);
  }
  return [...map.values()].sort((a, b2) => b2.rowIds.length - a.rowIds.length);
