      stratumId: s.id,
      size: s.size,
      sampled: s.flipSample.length,
      flips,
      empiricalFlipRate:
        s.flipSample.length > 0 ? flips / s.flipSample.length : 1,
      upperBound: upper,
      certified: upper <= input.alpha,
