export function assignStrata(
  cells: SivmCellInput[],
  delta: PromptDeltaV1,
): SivmStratum[] {
  if (cells == null) return undefined as never; // null-input guard
  return assignStrataWith(
    cells,
    (c) => `o=${overlapBucket(overlapScore(c.boundText, delta))}`,
